def main():
    session, _ = request({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "aquarium-side-project", "version": "1.0"}}})
    for image_id, name, boxes in ITEMS[int(os.environ.get("ROBOFLOW_BATCH_START", "0")):]:
        existing = tool("annotations_get", {"project_id": PROJECT, "image_ids": [image_id]}, session)["annotations"][0]
        if existing["annotation"].get("boxes"):
            tool("annotation_jobs_review_image", {"project_id": PROJECT, "job_id": JOB, "image_id": image_id, "status": "annotated"}, session)
            print(name, "already has boxes; skipped", flush=True)
            continue
        classes = list(dict.fromkeys(label for label, _ in boxes))
        class_ids = {label: i for i, label in enumerate(classes)}
        rows = []
        for label, (left, top, right, bottom) in boxes:
            assert 0 <= left < right <= SIDE and 0 <= top < bottom <= SIDE
            rows.append(f"{class_ids[label]} {(left + right) / (2 * SIDE):.6f} {(top + bottom) / (2 * SIDE):.6f} {(right - left) / SIDE:.6f} {(bottom - top) / SIDE:.6f}")
        tool("annotations_save", {"project_id": PROJECT, "image_id": image_id, "annotation_content": "\n".join(rows), "annotation_name": name, "labelmap": {str(i): label for label, i in class_ids.items()}, "add_to_dataset": True}, session)
        saved = tool("annotations_get", {"project_id": PROJECT, "image_ids": [image_id]}, session)["annotations"][0]
        if not saved["annotation_valid"] or len(saved["annotation"]["boxes"]) != len(boxes):
            raise RuntimeError(f"Saved geometry mismatch: {name}")
        tool("annotation_jobs_review_image", {"project_id": PROJECT, "job_id": JOB, "image_id": image_id, "status": "annotated"}, session)
        print(name, "saved", len(boxes), "boxes", flush=True)
    board = tool("annotation_board_status", {"project_id": PROJECT, "include_items": False}, session)
    print("Dataset:", board["dataset"]["annotated"], "annotated;", board["dataset"]["unannotated"], "unannotated", flush=True)


if __name__ == "__main__":
    main()
